import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { extname, join, normalize, resolve } from "node:path";

// Same logic as scripts/serve.js, exercised without binding a socket.
const root = resolve("public");
const types = { ".html":"text/html; charset=utf-8", ".css":"text/css; charset=utf-8", ".svg":"image/svg+xml", ".xml":"application/xml; charset=utf-8", ".txt":"text/plain; charset=utf-8" };
async function handle(pathname) {
  let rel = decodeURIComponent(pathname);
  if (rel.endsWith("/")) rel += "index.html";
  if (!extname(rel)) rel += ".html";
  const dest = join(root, normalize(rel).replace(/^(\.\.[/\\])+/, ""));
  if (!dest.startsWith(root)) return { status: 403, len: 9, type: "-" };
  try {
    const body = await readFile(dest);
    return { status: 200, len: body.length, type: (types[extname(dest)]||"application/octet-stream").split(";")[0] };
  } catch {
    try { const b = await readFile(join(root,"404.html")); return { status: 404, len: b.length, type: "text/html" }; }
    catch { return { status: 404, len: 9, type: "-" }; }
  }
}
const cases = ["/", "/index.html", "/blog.html", "/publications.html", "/posts/scaling-gnn-connectomics.html", "/assets/styles.css", "/assets/favicon.svg", "/sitemap.xml", "/robots.txt", "/does-not-exist", "/../../etc/passwd", "/%2e%2e/%2e%2e/etc/passwd"];
for (const c of cases) {
  const r = await handle(c);
  console.log(String(r.status).padEnd(4), String(r.len).padStart(7), c.padEnd(46), r.type);
}
' 2>&1; echo "EXIT=$?"

