import re,sys
lines=open('.github/workflows/deploy.yml').read().split('\n')
# structural sanity: tabs, indentation multiples, key/colon balance
bad=[]
for i,l in enumerate(lines,1):
    if '\t' in l: bad.append(f"line {i}: TAB character (YAML forbids tabs for indent)")
    if l.rstrip()!=l: bad.append(f"line {i}: trailing whitespace")
print("tab/ws issues:", bad or "none")
# collect uses: and permissions:
print("\n-- uses: --")
for i,l in enumerate(lines,1):
    if l.strip().startswith('uses:'):
        u=l.split('uses:',1)[1].strip()
        ok = re.fullmatch(r'[^@\s]+@[0-9a-f]{40}', u.split(' #')[0].strip())
        print(f"  {'OK ' if ok else 'BAD'} L{i}: {u}")
print("\n-- permissions blocks --")
for i,l in enumerate(lines,1):
    if re.match(r'\s*permissions:', l):
        print(f"  L{i}: {l.strip()}")
        for j in range(i,min(i+5,len(lines))):
            m=re.match(r'^(\s+)(\w[\w-]*):',lines[j])
            if m and len(m.group(1))>len(l)-len(l.lstrip()): print(f"       {lines[j].strip()}")
            elif lines[j].strip() and not lines[j].startswith(' '*(len(l)-len(l.lstrip())+1)): break
print("\n-- dangerous patterns --")
for pat in ['curl','wget','zip -r','hackerX','upload','pull_request_target','--privileged','secrets.']:
    hits=[f"L{i}:{l.strip()}" for i,l in enumerate(lines,1) if pat.lower() in l.lower() and not l.strip().startswith('#')]
    print(f"  {pat!r}: {hits if hits else 'none'}")
